#!/usr/bin/env bash
# Marracat — UI tests, smoke launch, bump build, archive, export, upload to TestFlight.
#
# The build number lives in project.yml (CURRENT_PROJECT_VERSION) because the
# pbxproj is generated by xcodegen and would be overwritten.
#
#   SIM_UDID=<free simulator> ./scripts/ship.sh
#   SHIP_SKIP_TESTS=1 ./scripts/ship.sh      # smoke launch only
#   UI_SIMS=3 ./scripts/ship.sh              # tests on three simulators (default 1)
#   SHIP_TIER=fast ./scripts/ship.sh         # unit tests + the nightly UI set (default full)
#   SHIP_TESTS_ONLY=1 ./scripts/ship.sh      # every gate, then stop: no bump, no upload
#                                            # (daily_ship.sh's quiet-Sunday full suite)
#   SHIP_FULL_CATALOG=1 ./scripts/ship.sh    # badge, audit and publish the catalog here
#                                            # even when the droplet's is fresh
#   CATALOG_MAX_AGE_HOURS=6                  # how old the droplet's catalog may be
#
# Order (2026-11-09): checks, catalog, smoke build, tests, perf, bump, archive,
# upload. The catalog is settled FIRST and not touched again, so the tests and
# the archive bundle the same one. Every run ends with one "SHIP SUMMARY" line
# (scripts/ship_summary.py): result, stage times, memory waits, memory peaks.
set -euo pipefail
cd "$(dirname "$0")/.."
# A ship runs 25-60 minutes; this Mac idle-sleeps on battery after a minute.
# daily_ship.sh already runs under caffeinate; a ship started by hand had no
# such cover (owner, 2026-11-09). Ends with this script; a closed lid still
# sleeps the Mac.
[[ -n "${DAILY_SHIP_AWAKE:-}" ]] || /usr/bin/caffeinate -i -w $$ &
# One build at a time on this Mac, shared with Find A Crib (scripts/build_lock.sh);
# under daily_ship.sh, which already holds it, this returns at once.
# shellcheck disable=SC1091
source scripts/build_lock.sh
build_lock_take "Marracat ship.sh"
# shellcheck disable=SC1091
source scripts/ship_log.sh
ship_log_start
# One trap: the summary, then the lock (build_lock_take set its own trap,
# which this replaces; the release only removes a lock this process holds).
# A ship that stops at a failed gate must still shut its simulator: a failed
# run left it booted (and ~3 GB held) until the next cleanup pass.
# "set +e" first and "exit $rc" last: under errexit a simulator that was
# already shut down failed the trap itself, so a ship that had uploaded build
# 180 exited 1 with no summary, and daily_ship.sh dropped the bump (2026-11-10).
trap 'rc=$?; set +e; [[ -n "${SIM_UDID:-}" ]] && xcrun simctl shutdown "$SIM_UDID" 2>/dev/null; ship_log_finish "$rc"; build_lock_release; exit "$rc"' EXIT
tests_only="${SHIP_TESTS_ONLY:-0}"
tier="${SHIP_TIER:-full}"
note "tier=$tier"
owner_notice() {
    echo "notice: $1"
    osascript -e "display notification \"$1\" with title \"Marracat ship\"" 2>/dev/null || true
}

PY="${PY:-$HOME/.venvs/marracat/bin/python}"

if [[ ! -f scripts/asc-config.env ]]; then
    echo "error: scripts/asc-config.env missing — copy asc-config.env.example" >&2
    exit 1
fi
# shellcheck disable=SC1091
source scripts/asc-config.env
if [[ -z "${ASC_APP_ID:-}" ]]; then
    echo "error: ASC_APP_ID is empty — run scripts/register_in_asc.py first" >&2
    exit 1
fi

ICON=Marracat/Assets.xcassets/AppIcon.appiconset/icon-1024.png
if sips -g hasAlpha "$ICON" | grep -q "hasAlpha: yes"; then
    echo "error: $ICON has an alpha channel — App Store validation rejects it" >&2
    exit 1
fi

export SIM_UDID="${SIM_UDID:-$(xcrun simctl list devices available | awk -F'[()]' '/iPhone 17 Pro \(/ {print $2; exit}')}"

# Apple's four quality checks run before every TestFlight upload, and follow the
# app as screens come and go (owner, 2026-10-03):
#   1. Swift Testing  — the @Test suites in MarracatTests must run
#   2. XCUITest       — every UI test incl. AccessibilityAuditTests (each tab it
#                       finds, product detail, light + dark, largest text size)
#   3. XCTMetric      — PerformanceTests, judged by scripts/perf_gate.py
#                       against the median of the last 5 passing ships
#   4. MetricKit      — Stores/MetricsReporter.swift still subscribed; the
#                       Xcode Organizer's field numbers printed (report only)
# plus scripts/coverage_gate.py: every screen file is executed by a test.
# The xcodeproj is generated and not in git: regenerate it BEFORE testing, or a
# Swift file added since the last generate is not in any target and its tests
# silently never run (found 2026-10-03: the new Swift Testing and audit suites
# were missing from the ship's test run until this line).
stage "app version"
# Once Apple approves a version its train closes (ITMS-90186): move to the next.
"$PY" scripts/next_version.py || { echo "error: could not check the app version" >&2; exit 1; }

stage "regenerating the xcodeproj"
xcodegen generate --quiet

stage "MetricKit still wired (metrics + diagnostics)"
grep -q "MXMetricManager.shared.add" Marracat/Stores/MetricsReporter.swift \
  && grep -q "\[MXDiagnosticPayload\]" Marracat/Stores/MetricsReporter.swift \
  && grep -rq "MetricsReporter.shared.start()" Marracat \
  || { echo "error: MetricsReporter (MetricKit) is no longer subscribed at launch" >&2; exit 1; }

# The catalog, settled before anything is built (2026-11-09). The refresh
# droplet rebuilds, badges, audits and publishes it every 3 hours
# (scripts/refresh_catalog.sh); until now every ship pulled that catalog and
# then ran the same 12 badge scripts and the publish again here: ~19 of a
# 43-minute nightly ship, re-publishing 195,045 products over the identical
# 195,045 already live. So:
#   fresh  (the droplet built it within CATALOG_MAX_AGE_HOURS): bundle it as
#          it is. Fold, audit, compact: about a minute.
#   stale, unreadable, or the pull failed: today's full path runs here as the
#          backstop, publish included, and the owner is told. The droplet was
#          stuck 2026-10-22..31 and the ship's publish was what kept the
#          catalog moving; that must never quietly stop.
# Pulling first also means the tests and the archive carry the same catalog
# (before, the tests ran on yesterday's and the archive bundled a newer one).
# A scheduled refresh on this Mac (scripts/refresh_catalog.sh) writes the same
# files; wait for one in progress to finish.
while [[ -d build/catalog-refresh.lock ]]; do echo "waiting for the catalog refresh to finish"; sleep 60; done
stage "taking the refresh droplet's latest catalog"
guard 4 "the catalog steps"
catalog_mode=mac; pulled=0
if ./scripts/pull_catalog.sh; then
    pulled=1
    if python3 scripts/catalog_freshness.py Marracat/Resources/catalog.json --max-hours "${CATALOG_MAX_AGE_HOURS:-6}"; then
        catalog_mode=droplet
    else
        owner_notice "The refresh droplet's catalog is stale; this ship is badging and publishing it from the Mac. Check the droplet."
    fi
else
    echo "warning: could not pull the latest catalog; using the one on this Mac" >&2
    owner_notice "Could not pull the catalog from the refresh droplet; this ship is badging the copy on the Mac."
fi
if [[ ! -f Marracat/Resources/catalog.json ]]; then
    echo "error: Marracat/Resources/catalog.json is missing — it is build output now." >&2
    echo "  rebuild it: $PY catalog/build_catalog.py --cached" >&2
    exit 1
fi
[[ "${SHIP_FULL_CATALOG:-0}" == 1 ]] && catalog_mode=mac
# A tests-only run publishes nothing, whatever the catalog's age.
[[ "$tests_only" == 1 && "$catalog_mode" == mac ]] && catalog_mode=mac-unpublished
note "catalog=$catalog_mode"
echo "   catalog: $catalog_mode"

stage "folding repeat listings"
# Same brand + same title + same-looking photo = one product the store listed
# more than once (sizes, formats, re-uploads). Needs Pillow, hence the venv.
# Before the tests read the catalog: DuplicateListingTests failed the 10/25
# ships on a pair a later fold would have caught.
"$PY" catalog/dedupe_products.py

if [[ "$catalog_mode" == mac ]]; then
    stage "clean badge"
    # Reads ingredient lists already stored in catalog/ingredients.json, fetches
    # lists for products added since the last ship (bounded), and rewrites the
    # `clean` flags. The report at catalog/clean_report.md is where a bad list
    # extraction or a new banned ingredient shows up first.
    python3 catalog/clean_badge.py --scrape --max-new 300

    stage "true metal badge"
    # The jewelry badge reads only what each listing says (catalog/metal_badge.py,
    # standard in catalog/metal_standard.md); catalog/metal_report.md shows why
    # products fail.
    python3 catalog/metal_badge.py

    stage "clear scent and safer clean badges"
    # Fragrance and household cleaners, from published ingredient lists stored
    # beside Clean's (catalog/scent_standard.md, catalog/safer_clean_standard.md).
    # Each run reads at most 200 new pages; the reports show why products fail.
    python3 catalog/scent_badge.py --scrape --max-new 200
    python3 catalog/safer_clean_badge.py --scrape --max-new 200

    stage "clean food and baby safe badges"
    # Groceries and baby products (catalog/food_standard.md, catalog/baby_standard.md):
    # lists and materials from each description, plus at most 200 new pages a run.
    python3 catalog/food_badge.py --scrape --max-new 200
    python3 catalog/baby_badge.py --scrape --max-new 200

    stage "natural fiber and safe fabric badges"
    # Garments (catalog/fiber_standard.md, catalog/fabric_standard.md): from each
    # listing's stated composition; nothing is fetched.
    python3 catalog/fiber_badge.py
    python3 catalog/fabric_badge.py

    stage "lab verified, pet safe, true material and natural home badges"
    # Wellness, pets, bags and home (catalog/lab_standard.md, pet_standard.md,
    # material_standard.md, home_standard.md): read from each listing; pet grooming
    # ingredient lists are fetched with a cap.
    python3 catalog/lab_badge.py
    python3 catalog/pet_badge.py --scrape --max-new 200
    python3 catalog/material_badge.py
    python3 catalog/home_badge.py
fi

stage "auditing categories"
# Every misfile found by hand has been one of these shapes. The gate is a
# ratchet: if a keyword or a new brand pushes more products into the risky
# buckets than the catalog carries today, the ship stops and it gets read.
# Kept on the droplet's catalog too: 35 s over the exact file being bundled.
python3 catalog/audit_categories.py --max-risky 30

stage "building the bundled catalog"
python3 catalog/make_compact.py

if [[ "$catalog_mode" == mac ]]; then
    # Never put an older catalog over a newer live one: with no pull, publish
    # only when this Mac's copy is at least as new as what marracat.com serves.
    if [[ "$pulled" == 1 ]] || python3 scripts/catalog_freshness.py Marracat/Resources/catalog.json \
            --not-older-than https://marracat.com/catalog-v3.json; then
        stage "publishing the catalog"
        ./scripts/publish_catalog.sh
    else
        echo "warning: not publishing: no pull, and this Mac's catalog is not known to be newer than the live one" >&2
    fi
fi

# One build for every simulator pass (2026-11-09): the smoke step builds the
# app AND the test bundles (build-for-testing), and the fast tier's tests, the
# quarantine pass and each performance run start from those products with
# test-without-building. Before, each pass was its own `xcodebuild test`, and
# the coverage flag on the main run recompiled the app twice over (once
# instrumented for the tests, once plain again for the performance run).
stage "smoke test"
echo "   cold launch on $SIM_UDID"
# Room under the Mac's 15 GB before each heavy step (owner, 2026-11-01;
# scripts/ram_guard.sh waits, then goes on after 20 minutes).
guard 6 "the smoke build and a simulator"
if [[ "${SHIP_SKIP_TESTS:-0}" != "1" ]]; then SMOKE_ACTION=build-for-testing ./scripts/smoke_test.sh; else ./scripts/smoke_test.sh; fi

if [[ "${SHIP_SKIP_TESTS:-0}" != "1" ]]; then
    stage "UI tests"
    guard 6 "the UI tests"
    # The guard can wait 20 minutes with nothing using the simulator, and the
    # close-simulators hook or the cleanup job may shut it down meanwhile.
    # xcodebuild then boots it itself and every launch is refused ("Application
    # failed preflight checks"): all 121 tests failed that way on 2026-11-16
    # and twice on 2026-11-20, each time after the simulator went down during
    # the wait. Booted and settled by hand first, the same tests pass.
    xcrun simctl boot "$SIM_UDID" 2>/dev/null || true
    xcrun simctl bootstatus "$SIM_UDID" -b >/dev/null
    # A UI test that fails once is retried once: the suite flakes on a loaded
    # machine (a different three failed each run on 2026-09-22, every one of
    # them passing on its own). A test that is actually broken fails twice.
    # One simulator. Three clones of SIM_UDID (UI_SIMS=3) were tried on
    # 2026-10-17: 37 min against 39, each test ~1.6x slower on the 16 GB Mac,
    # and the search-speed checks failed under the load, so the owner went
    # back to one. Xcode hands out whole classes, so the big UI class stays
    # split three ways by run time (MarracatUITests, 2, 3) for a faster Mac.
    # Tiers (owner, 2026-10-25: "fast set nightly"): SHIP_TIER=fast runs every
    # unit test and MarracatUITests/fast-tests.txt, the accessibility audit in
    # light mode only; full (the default, and daily_ship.sh on Sundays) runs
    # everything. Quarantined flaky tests (MarracatUITests/quarantine.txt) are
    # skipped here and run on their own below, where they can't fail the ship.
    # scripts/flaky_tests.py picks the tests and keeps the quarantine.
    read -r -a selection <<<"$(python3 scripts/flaky_tests.py args "$tier")"
    a11y_looks=$([[ "$tier" == fast ]] && echo light || echo all)
    echo "   tier: $tier (${#selection[@]} test selections)"
    rm -rf build/gates/Ship.xcresult build/gates/Perf.xcresult build/gates/Quarantine.xcresult; mkdir -p build/gates
    SIM=(-project Marracat.xcodeproj -scheme Marracat -destination "platform=iOS Simulator,id=$SIM_UDID" -quiet)
    gate_rc=0
    if [[ "$tier" == full ]]; then
        # The coverage gate needs an instrumented build. It gets its own
        # DerivedData (build/cov, full tier only) so the plain products in
        # build/smoke stay as they are for the quarantine and performance
        # passes: performance must never be measured on instrumented code.
        TEST_RUNNER_A11Y_LOOKS="$a11y_looks" xcodebuild "${SIM[@]}" -derivedDataPath build/cov \
            -parallel-testing-enabled "$([[ ${UI_SIMS:-1} -gt 1 ]] && echo YES || echo NO)" -parallel-testing-worker-count "${UI_SIMS:-1}" \
            -retry-tests-on-failure -test-iterations 2 \
            -enableCodeCoverage YES -resultBundlePath build/gates/Ship.xcresult \
            -skip-testing:MarracatUITests/PerformanceTests ${selection[@]+"${selection[@]}"} test 2>&1 | tee build/gates/ship-tests.log || gate_rc=$?
    else
        TEST_RUNNER_A11Y_LOOKS="$a11y_looks" xcodebuild "${SIM[@]}" -derivedDataPath build/smoke \
            -parallel-testing-enabled "$([[ ${UI_SIMS:-1} -gt 1 ]] && echo YES || echo NO)" -parallel-testing-worker-count "${UI_SIMS:-1}" \
            -retry-tests-on-failure -test-iterations 2 \
            -resultBundlePath build/gates/Ship.xcresult \
            -skip-testing:MarracatUITests/PerformanceTests ${selection[@]+"${selection[@]}"} test-without-building 2>&1 | tee build/gates/ship-tests.log || gate_rc=$?
    fi
    read -r -a held <<<"$(python3 scripts/flaky_tests.py quarantined "$tier")"
    if [[ ${#held[@]} -gt 0 ]]; then
        stage "quarantined UI tests (${#held[@]}, reported, never fail the ship)"
        TEST_RUNNER_A11Y_LOOKS="$a11y_looks" xcodebuild "${SIM[@]}" -derivedDataPath build/smoke \
            -resultBundlePath build/gates/Quarantine.xcresult "${held[@]}" test-without-building >build/gates/quarantine-tests.log 2>&1 || true
    fi
    python3 scripts/flaky_tests.py record "$tier" build/gates/Ship.xcresult build/gates/Quarantine.xcresult || true
    [[ $gate_rc -eq 0 ]] || { echo "error: UI tests failed (see Failing tests above)" >&2; exit "$gate_rc"; }
    # xcodebuild passes with zero tests run; make each gate prove it ran
    # Swift Testing cases are the ones not named test…() (XCTest's convention);
    # -quiet hides the "Test run with N tests" line, so count them in the bundle.
    xcrun xcresulttool get test-results tests --path build/gates/Ship.xcresult | python3 -c '
import json, sys
n = 0
def walk(node):
    global n
    for c in node.get("children", []):
        if c.get("nodeType") == "Test Case" and not c["name"].startswith("test") and c.get("result") == "Passed":
            n += 1
        walk(c)
for t in json.load(sys.stdin)["testNodes"]:
    walk(t)
print(f"Swift Testing: {n} test(s) passed")
sys.exit(0 if n else 1)' || { echo "error: no Swift Testing tests ran" >&2; exit 1; }
    # Read the whole list before searching it: `xcresulttool | grep -q` under
    # pipefail fails when grep stops at the first match and the full suite's
    # 300 KB list SIGPIPEs xcresulttool (exit 141; 1.12 (179), 2026-11-09).
    ran=$(xcrun xcresulttool get test-results tests --path build/gates/Ship.xcresult)
    [[ "$ran" == *'"AccessibilityAuditTests"'* ]] \
        || { echo "error: the accessibility audit did not run" >&2; exit 1; }
    # The fast set covers journeys, not every screen: the coverage gate is the
    # weekly full run's.
    if [[ "$tier" == full ]]; then
        stage "every screen is exercised by a test"
        python3 scripts/coverage_gate.py build/gates/Ship.xcresult
    fi
    stage "performance"
    ./scripts/wait_sim_quiet.sh
    xcodebuild "${SIM[@]}" -derivedDataPath build/smoke \
        -resultBundlePath build/gates/Perf.xcresult -only-testing:MarracatUITests/PerformanceTests test-without-building
    # One noisy run doesn't fail a ship: on a failure, two more runs, and the
    # gate judges the median of all three (scripts/perf_gate.py). A tests-only
    # run judges but records nothing: the baseline is the shipped builds'.
    record=--record; [[ "$tests_only" == 1 ]] && record=
    if ! python3 scripts/perf_gate.py build/gates/Perf.xcresult; then
        for n in 2 3; do
            stage "performance, run $n of 3"
            rm -rf "build/gates/Perf$n.xcresult"
            ./scripts/wait_sim_quiet.sh
            xcodebuild "${SIM[@]}" -derivedDataPath build/smoke \
                -resultBundlePath "build/gates/Perf$n.xcresult" -only-testing:MarracatUITests/PerformanceTests test-without-building
        done
        python3 scripts/perf_gate.py build/gates/Perf.xcresult build/gates/Perf2.xcresult build/gates/Perf3.xcresult $record
    elif [[ -n "$record" ]]; then
        python3 scripts/perf_gate.py build/gates/Perf.xcresult --record >/dev/null
    fi
fi

# One simulator at a time, shut down when its pass ends (owner rule for all apps,
# 2026-10-21: a Find A Crib ship was killed for low memory on this 16 GB Mac).
xcrun simctl shutdown "$SIM_UDID" 2>/dev/null || true

if [[ "$tests_only" == 1 ]]; then
    stage "tests only: every gate passed, nothing bumped or uploaded"
    exit 0
fi

stage "Xcode Organizer: what real phones reported for recent builds"
"$PY" scripts/organizer_report.py || echo "warning: Organizer report unavailable"

current=$(grep -m1 'CURRENT_PROJECT_VERSION:' project.yml | sed -E 's/.*"([0-9]+)".*/\1/')
next=$((current + 1))
note "build=$next"
stage "bumping build $current -> $next"
sed -i '' "s/CURRENT_PROJECT_VERSION: \"$current\"/CURRENT_PROJECT_VERSION: \"$next\"/" project.yml
xcodegen generate --quiet

AUTH=(-authenticationKeyPath "$ASC_KEY_PATH" -authenticationKeyID "$ASC_KEY_ID"
      -authenticationKeyIssuerID "$ASC_ISSUER_ID")

# The tests take hours, and Apple can approve the version meanwhile: 1.8 went
# live between the 03:00 version check and the 09:13 upload on 2026-10-22, and
# the upload was refused (ITMS-90186). So check again just before archiving,
# and if the train still closes before the upload lands, move on and redo it.
release() {
    stage "app version, just before archiving"
    "$PY" scripts/next_version.py || { echo "error: could not check the app version" >&2; exit 1; }
    xcodegen generate --quiet

    stage "archiving"
    guard 6 "the release archive"
    rm -rf build/release
    xcodebuild -project Marracat.xcodeproj -scheme Marracat -configuration Release \
        -destination "generic/platform=iOS" -archivePath build/release/Marracat.xcarchive \
        -allowProvisioningUpdates "${AUTH[@]}" DEVELOPMENT_TEAM="$ASC_TEAM_ID" -quiet archive

    stage "exporting IPA"
    # Apple's tools first (2026-10-12): Xcode's IPA step runs /usr/bin/rsync, which
    # starts the rsync on PATH as its receiving side. A Homebrew rsync 3.x there
    # rejects --extended-attributes and the export dies with just "Copy failed".
    PATH="/usr/bin:/bin:/usr/sbin:/sbin:$PATH" xcodebuild -exportArchive -archivePath build/release/Marracat.xcarchive \
        -exportPath build/release/export -exportOptionsPlist scripts/ExportOptions.plist \
        -allowProvisioningUpdates "${AUTH[@]}"

    stage "uploading to App Store Connect"
    xcrun altool --upload-app -f build/release/export/Marracat.ipa -t ios \
        --apiKey "$ASC_KEY_ID" --apiIssuer "$ASC_ISSUER_ID" 2>&1 | tee build/release/upload.log || true
}
release
if grep -q "90186" build/release/upload.log; then
    stage "the version's train closed during the ship; moving on and uploading again"
    release
fi
grep -qE "UPLOAD SUCCEEDED|No errors uploading" build/release/upload.log \
    || { echo "error: upload failed; see above" >&2; exit 1; }

stage "internal TestFlight group"
"$PY" scripts/configure_internal_testers.py

echo "==> $(date +%T) shipped build $next — Apple takes a few minutes to process it before it appears in TestFlight."
